			new() { SeedIdentifier = "MF26_133", Name = "Neurologie", Description = @"Na přednášce se podíváme, jak se z přírodních steroidů v hlavě stávají moderní léky na deprese, epilepsii, poruchy autistického spektra, nespavost nebo poranění mozku – a proč někdy tyto látky můžou mozek naopak rozhodit. Ukážeme si i roli vitaminu D jako mozkového steroidu a to, proč hormony během puberty, těhotenství nebo menopauzy tak dramaticky mění prožívání světa. Přijďte zjistit, jak malé molekuly, o kterých většinou vůbec nevíte, potichu rozhodují o tom, jak se cítíte, jak spíte, jak se soustředíte – a jak by z nich jednou mohly být chytré aktualizace pro mozek budoucnosti.", Capacity = 40, ScheduleDayOfWeek = DayOfWeek.Monday, ScheduleSlotInDay = (ScheduleSlotInDay)3, TeacherRelations = { new SubjectTeacherRelation() { TeacherId = users.First(t => t.Name.Contains("Kudová")).TeacherId.Value } }, TypeRelations = { new SubjectTypeRelation() { SubjectTypeId = (int)SubjectType.Entry.Informatics } }, GradeRelations = { new SubjectGradeRelation() { GradeId = (int)GradeEntry.Prima }, new SubjectGradeRelation() { GradeId = (int)GradeEntry.Sekunda }, new SubjectGradeRelation() { GradeId = (int)GradeEntry.Tercie }, new SubjectGradeRelation() { GradeId = (int)GradeEntry.Kvarta }, new SubjectGradeRelation() { GradeId = (int)GradeEntry.Kvinta }, new SubjectGradeRelation() { GradeId = (int)GradeEntry.Sexta }, new SubjectGradeRelation() { GradeId = (int)GradeEntry.Septima }, new SubjectGradeRelation() { GradeId = (int)GradeEntry.Oktava }, }, CategoryId = (int)SubjectCategory.Entry.GraduationSeminar },

