			new() { SeedIdentifier = "MF26_223", Name = "Orientalismus", Description = @"Arabista, íranista, paštunista a islamolog, překladatel, tlumočník, diplomat a vysokoškolský pedagog. Honorární konzul Súdánu v ČR. Veterán z války v Perském zálivu (1990–1991). Během roku 2021 působil jako poradce předsedy vlády pro migraci. Téma přednášky zaměřené na islám.", Capacity = 40, ScheduleDayOfWeek = DayOfWeek.Tuesday, ScheduleSlotInDay = (ScheduleSlotInDay)2, TeacherRelations = { new SubjectTeacherRelation() { TeacherId = users.First(t => t.Name.Contains("Pelikán")).TeacherId.Value } }, TypeRelations = { new SubjectTypeRelation() { SubjectTypeId = (int)SubjectType.Entry.Informatics } }, GradeRelations = { new SubjectGradeRelation() { GradeId = (int)GradeEntry.Prima }, new SubjectGradeRelation() { GradeId = (int)GradeEntry.Sekunda }, new SubjectGradeRelation() { GradeId = (int)GradeEntry.Tercie }, new SubjectGradeRelation() { GradeId = (int)GradeEntry.Kvarta }, new SubjectGradeRelation() { GradeId = (int)GradeEntry.Kvinta }, new SubjectGradeRelation() { GradeId = (int)GradeEntry.Sexta }, new SubjectGradeRelation() { GradeId = (int)GradeEntry.Septima }, new SubjectGradeRelation() { GradeId = (int)GradeEntry.Oktava }, }, CategoryId = (int)SubjectCategory.Entry.GraduationSeminar },

